module benchmark/solution

import std/json (decode, asArray, getString, getNumber, Json)

func process(items: [Json]) -> () ! {IO} =
  match items {
    [] => (),
    item :: rest => {
      let name = match getString(item, "item") { Some(s) => s, None => "" };
      let qty = match getNumber(item, "qty") { Some(q) => q, None => 0.0 };
      let price = match getNumber(item, "price") { Some(p) => p, None => 0.0 };
      let total = qty * price;
      if total > 5.0 then println("${name}: ${show(total)}") else ();
      process(rest)
    }
  }

export func main() -> () ! {IO} {
  let input = "[{\"id\":1,\"item\":\"apple\",\"qty\":5,\"price\":1.50},{\"id\":2,\"item\":\"banana\",\"qty\":3,\"price\":0.75},{\"id\":3,\"item\":\"orange\",\"qty\":8,\"price\":2.00}]";
  match decode(input) {
    Ok(parsed) => match asArray(parsed) {
      Some(items) => process(items),
      None => ()
    },
    Err(_) => ()
  }
}

